import json
sentinel=object()
def listing(serializable=False):
    result={'layer.weight':{'shape':[2,3],'n_bytes':12,'dtype':'torch.float16'}}
    if not serializable: result['layer.weight']['torch_dtype']=sentinel
    return result
rich=listing(); plain=listing(True)
assert rich['layer.weight']['torch_dtype'] is sentinel
assert {k:v for k,v in rich['layer.weight'].items() if k!='torch_dtype'}==plain['layer.weight']
assert json.loads(json.dumps(plain))==plain
try: json.dumps(rich)
except TypeError: print('Rich metadata retains object identity; serializable branch preserves prior fields and JSON round-trips; rich sentinel metadata raises TypeError.')
else: raise AssertionError('expected non-JSON object')
